from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
import re

out = '/root/output/result.xlsx'
wb = load_workbook(out, data_only=False)
ws = wb['Task']

print('Validation samples from reopened workbook (data_only=False):')
for coord in ['H12', 'H35', 'H42', 'H50']:
    print(f'  {coord} = {ws[coord].value}')

# Validate target ranges are all formula strings.
target_ranges = [(12, 17), (19, 24), (26, 31), (35, 40), (42, 47), (50, 50)]
missing = []
not_formula = []
for start, end in target_ranges:
    for row in range(start, end + 1):
        for col in range(8, 13):
            coord = f'{get_column_letter(col)}{row}'
            v = ws.cell(row=row, column=col).value
            if v is None:
                missing.append(coord)
            elif not (isinstance(v, str) and v.startswith('=')):
                not_formula.append((coord, v))

print('\nNone cells in target ranges:', missing if missing else 'NONE')
print('Non-formula cells in target ranges:', not_formula if not_formula else 'NONE')

# Syntax/reference checks for expected formula families.
errors = []
lookup_re = re.compile(r'^=INDEX\(Data!\$H\$21:\$L\$38, MATCH\(\$D\d+, Data!\$D\$21:\$D\$38, 0\), MATCH\([H-L]\$10, Data!\$H\$4:\$L\$4, 0\)\)$')
for row in list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32)):
    for col in range(8, 13):
        coord = f'{get_column_letter(col)}{row}'
        if not lookup_re.match(ws[coord].value or ''):
            errors.append((coord, 'lookup formula mismatch', ws[coord].value))

for idx, row in enumerate(range(35, 41)):
    for col in range(8, 13):
        c = get_column_letter(col)
        expected = f'=({c}{12+idx}-{c}{19+idx})/{c}{26+idx}*100'
        if ws.cell(row, col).value != expected:
            errors.append((f'{c}{row}', 'net flow mismatch', ws.cell(row, col).value, expected))

for col in range(8, 13):
    c = get_column_letter(col)
    expected_by_row = {
        42: f'=MIN({c}35:{c}40)',
        43: f'=MAX({c}35:{c}40)',
        44: f'=MEDIAN({c}35:{c}40)',
        45: f'=AVERAGE({c}35:{c}40)',
        46: f'=PERCENTILE({c}35:{c}40, 0.25)',
        47: f'=PERCENTILE({c}35:{c}40, 0.75)',
        50: f'=SUMPRODUCT({c}35:{c}40, {c}26:{c}31) / SUM({c}26:{c}31)',
    }
    for row, expected in expected_by_row.items():
        if ws.cell(row, col).value != expected:
            errors.append((f'{c}{row}', 'summary/weighted mismatch', ws.cell(row, col).value, expected))

print('Formula syntax/reference errors:', errors if errors else 'NONE')

# Confirm no extra sheets were added.
print('Sheet names after save:', wb.sheetnames)

if missing or not_formula or errors or wb.sheetnames != ['Task', 'Data']:
    raise SystemExit(1)
print('\nVALIDATION PASSED')
